 "CREATE TABLE IF NOT EXISTS \"question_bank_question\" (\n  \"id\" TEXT PRIMARY KEY,\n  \"created_at\" TEXT NOT NULL,\n  \"updated_at\" TEXT NOT NULL,\n  \"subject_id\" TEXT NOT NULL,\n  \"origin_type\" TEXT NOT NULL DEFAULT 'demo',\n  \"current_published_version_id\" TEXT,\n  \"family_id\" TEXT,\n  \"content_lineage_id\" TEXT,\n  \"created_by_id\" TEXT,\n  \"is_demo\" INTEGER NOT NULL DEFAULT 1,\n  \"display_label\" TEXT NOT NULL,\n  FOREIGN KEY (\"subject_id\") REFERENCES \"exams_subject\" (\"id\") ON DELETE CASCADE,\n  FOREIGN KEY (\"current_published_version_id\") REFERENCES \"question_bank_question_version\" (\"id\") ON DELETE SET NULL,\n  FOREIGN KEY (\"family_id\") REFERENCES \"question_bank_family\" (\"id\") ON DELETE SET NULL,\n  FOREIGN KEY (\"content_lineage_id\") REFERENCES \"question_bank_content_lineage\" (\"id\") ON DELETE SET NULL,\n  FOREIGN KEY (\"created_by_id\") REFERENCES \"accounts_user\" (\"id\") ON DELETE SET NULL\n)",
