 "CREATE TABLE IF NOT EXISTS \"question_bank_pool_policy\" (\n  \"id\" TEXT PRIMARY KEY,\n  \"created_at\" TEXT NOT NULL,\n  \"updated_at\" TEXT NOT NULL,\n  \"project_id\" TEXT NOT NULL,\n  \"family_id\" TEXT,\n  \"question_id\" TEXT,\n  \"revision\" INTEGER NOT NULL DEFAULT 1,\n  \"is_holdout\" INTEGER NOT NULL DEFAULT 0,\n  \"change_reason\" TEXT NOT NULL,\n  \"changed_by_id\" TEXT,\n  FOREIGN KEY (\"project_id\") REFERENCES \"exams_project\" (\"id\") ON DELETE CASCADE,\n  FOREIGN KEY (\"family_id\") REFERENCES \"question_bank_family\" (\"id\") ON DELETE CASCADE,\n  FOREIGN KEY (\"question_id\") REFERENCES \"question_bank_question\" (\"id\") ON DELETE CASCADE,\n  FOREIGN KEY (\"changed_by_id\") REFERENCES \"accounts_user\" (\"id\") ON DELETE SET NULL,\n  CONSTRAINT \"pool_policy_target_required\" CHECK ((\"question_bank_pool_policy\".\"family_id\" IS NOT NULL OR \"question_bank_pool_policy\".\"question_id\" IS NOT NULL))\n)",
 "CREATE TABLE IF NOT EXISTS \"question_bank_source_link\" (\n  \"id\" TEXT PRIMARY KEY,\n  \"created_at\" TEXT NOT NULL,\n  \"updated_at\" TEXT NOT NULL,\n  \"question_version_id\" TEXT NOT NULL,\n  \"region_id\" TEXT NOT NULL,\n  \"role\" TEXT NOT NULL DEFAULT 'stem',\n  \"note\" TEXT NOT NULL,\n  FOREIGN KEY (\"question_version_id\") REFERENCES \"question_bank_question_version\" (\"id\") ON DELETE CASCADE,\n  FOREIGN KEY (\"region_id\") REFERENCES \"ingestion_source_region\" (\"id\") ON DELETE RESTRICT,\n  CONSTRAINT \"uniq_version_region_role\" UNIQUE (\"question_version_id\", \"region_id\", \"role\")\n)",
 "CREATE TABLE IF NOT EXISTS \"question_bank_question_version\" (\n  \"id\" TEXT PRIMARY KEY,\n  \"created_at\" TEXT NOT NULL,\n  \"updated_at\" TEXT NOT NULL,\n  \"question_id\" TEXT NOT NULL,\n  \"version\" INTEGER NOT NULL DEFAULT 1,\n  \"question_type\" TEXT NOT NULL,\n  \"content\" TEXT NOT NULL,\n  \"parent_material_version_id\" TEXT,\n  \"material_child_version_ids\" TEXT NOT NULL,\n  \"practice_max_score\" TEXT,\n  \"estimated_seconds\" INTEGER,\n  \"status\" TEXT NOT NULL DEFAULT 'draft',\n  \"revision_reason\" TEXT NOT NULL,\n  \"source_note\" TEXT NOT NULL,\n  \"created_by_id\" TEXT,\n  \"published_at\" TEXT,\n  \"withdrawn_at\" TEXT,\n  \"withdrawn_reason\" TEXT NOT NULL,\n  \"content_digest\" TEXT NOT NULL,\n  CONSTRAINT \"json_content\" CHECK (json_valid(\"content\")),\n  CONSTRAINT \"json_material_child_version_ids\" CHECK (json_valid(\"material_child_version_ids\")),\n  FOREIGN KEY (\"question_id\") REFERENCES \"question_bank_question\" (\"id\") ON DELETE CASCADE,\n  FOREIGN KEY (\"parent_material_version_id\") REFERENCES \"question_bank_question_version\" (\"id\") ON DELETE RESTRICT,\n  FOREIGN KEY (\"created_by_id\") REFERENCES \"accounts_user\" (\"id\") ON DELETE SET NULL,\n  CONSTRAINT \"uniq_question_version\" UNIQUE (\"question_id\", \"version\")\n)",
