 "CREATE TABLE IF NOT EXISTS \"tutoring_turn\" (\n  \"id\" TEXT PRIMARY KEY,\n  \"created_at\" TEXT NOT NULL,\n  \"updated_at\" TEXT NOT NULL,\n  \"tutor_session_id\" TEXT NOT NULL,\n  \"role\" TEXT NOT NULL DEFAULT 'user',\n  \"text\" TEXT NOT NULL,\n  \"job_id\" TEXT,\n  FOREIGN KEY (\"tutor_session_id\") REFERENCES \"tutoring_session\" (\"id\") ON DELETE CASCADE,\n  FOREIGN KEY (\"job_id\") REFERENCES \"tutoring_job\" (\"id\") ON DELETE SET NULL\n)"
